"""Fail-closed, auditable summary; never creates a release or claims certification."""
from __future__ import annotations

import os
import sys


def main() -> int:
    observed = {job: os.environ.get(job, "unknown") for job in ("REGRESSION", "BROWSER", "PACKAGE", "LOGGING_SECURITY", "DEPENDENCY_AUDIT", "PROXY")}
    blocked = [f"{job}: {result}" for job, result in observed.items() if result != "success"]
    lines = [
        "## stealth-engine — CI release-gate overview",
        "",
        "| Required job | GitHub Actions result |",
        "|---|---|",
        *[f"| {job.lower()} | {status} |" for job, status in observed.items()],
        "",
        "**CI verdict:** " + ("BLOCKED" if blocked else "AUTOMATED JOBS PASSED"),
        "",
        "**Production certification:** NOT ESTABLISHED by this workflow alone.",
        "Windows NTFS ACL acceptance and external DNS/WebRTC leak checks,",
        "full generated-to-visible fingerprint parity, and F-19 module-global logging",
        "security gap require independently recorded acceptance evidence.",
        "No tags, releases or deployments are generated by this workflow.",
    ]
    if blocked:
        lines.append("\nBlocking jobs: " + ", ".join(blocked))
    result = "\n".join(lines) + "\n"
    print(result)
    if os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(os.environ["GITHUB_STEP_SUMMARY"], "a", encoding="utf-8") as target:
            target.write(result)
    return 1 if blocked else 0


if __name__ == "__main__":
    raise SystemExit(main())
